2	import {
3	  ref,
4	  computed,
5	  useSlots,
6	  onMounted,
7	  onBeforeUnmount,
8	  nextTick,
9	} from 'vue';
10	
11	/**
12	 * A dependency-free slide carousel. Each direct child element of the default
13	 * slot becomes one slide; dots navigate, arrows step, swipe works on touch —
14	 * EXCEPT on narrow screens, where slides often contain horizontally
15	 * scrollable tables: there a horizontal pan must scroll the table, never
16	 * flick the slide, so swipe is disabled and the arrows move under the slide
17	 * beside the dots. No autoplay — numbers are for reading, not for racing.
18	 */
19	const slots = useSlots();
20	const activeIndex = ref(0);
21	const trackElement = ref<HTMLElement | null>(null);
22	const viewportHeight = ref<number | null>(null);
23	
24	const slideCount = computed(() => {
25	  const children = slots.default?.() ?? [];
26	  return children.filter((node) => typeof node.type !== 'symbol').length;
27	});
28	
29	// The viewport's height follows the ACTIVE slide, so a short slide is not
30	// padded out to the tallest sibling's height. A ResizeObserver keeps the
31	// measurement honest when late content (images, fonts) changes the slide.
32	let resizeObserver: ResizeObserver | null = null;
33	function measureActiveSlide() {
34	  const slide = trackElement.value?.children[activeIndex.value] as
35	    | HTMLElement
36	    | undefined;
37	  if (!slide) return;
38	  viewportHeight.value = slide.offsetHeight;
39	  if (typeof ResizeObserver !== 'undefined') {
40	    resizeObserver?.disconnect();
41	    resizeObserver = new ResizeObserver(() => {
42	      viewportHeight.value = slide.offsetHeight;
43	    });
44	    resizeObserver.observe(slide);
45	  }
46	}
47	
48	function goTo(index: number) {
49	  const count = slideCount.value;
50	  activeIndex.value = ((index % count) + count) % count;
51	  nextTick(measureActiveSlide);
52	}
53	
54	onMounted(measureActiveSlide);
55	onBeforeUnmount(() => resizeObserver?.disconnect());
56	
57	function isNarrowScreen(): boolean {
58	  return (
59	    typeof window !== 'undefined' &&
60	    window.matchMedia('(max-width: 719px)').matches
61	  );
62	}
63	
64	let touchStartX = 0;
65	function onTouchStart(event: TouchEvent) {
66	  touchStartX = event.touches[0]?.clientX ?? 0;
67	}
68	function onTouchEnd(event: TouchEvent) {
69	  // On narrow screens a horizontal pan belongs to the slide's own
70	  // scrollable content (tables) — never steal it for slide navigation.
71	  if (isNarrowScreen()) return;
72	  const deltaX = (event.changedTouches[0]?.clientX ?? 0) - touchStartX;
73	  if (Math.abs(deltaX) > 40) goTo(activeIndex.value + (deltaX < 0 ? 1 : -1));
74	}
75	</script>
