const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 1280, height: 900 } });
  // delay every invar SVG by 2s to simulate lazy/not-yet-loaded slides
  await p.route('**/invar-*.svg', async (route) => {
    await new Promise((r) => setTimeout(r, 2000));
    route.continue();
  });
  await p.goto('http://localhost:5174/', { waitUntil: 'domcontentloaded' });
  await p.waitForTimeout(1500);
  const slider = await p.\$('.invar-production .perf-slider');
  await slider.scrollIntoViewIfNeeded();
  await p.waitForTimeout(300);
  const vh = () => p.evaluate(() => Math.round(document.querySelector('.invar-production .perf-slider-viewport').getBoundingClientRect().height));
  const h0 = await vh();
  // slide IMMEDIATELY while images are still delayed
  await p.click('.invar-production .perf-slider-arrow.next');
  await p.waitForTimeout(150);
  const hDuring = await vh();
  await p.waitForTimeout(2500); // images arrive
  const hAfter = await vh();
  await p.click('.invar-production .perf-slider-arrow.next');
  await p.waitForTimeout(500);
  const hSlide3 = await vh();
  console.log(JSON.stringify({ h0, hDuring, hAfter, hSlide3, stable: h0 === hDuring && hDuring === hAfter && hAfter === hSlide3 }));
  await b.close();
})();
"

