/* Kill the ~300ms tap delay Safari can add while waiting to rule out
   a double-tap gesture — the single biggest "heavy click" feel on iOS */
.VPNavBarHamburger,
.VPNavScreen a,
.VPNavScreen button,
.VPLocalNav button {
  touch-action: manipulation;
}

/* (The iOS animation kill-switches that lived here were chasing the
   wrong suspect — the real menu-open jank was filter: blur(90px) on
   the hero glow blobs. See LESSONS.md: "filter: blur on large
   elements". All animations are back to full everywhere.) */

/* NOTE: no body:has(.VPNavScreen) rules here — :has() on body makes
   Safari restyle the whole document the moment the menu mounts, which
   is the exact interaction we're protecting. */

/* Home page below-fold sections: skip layout/paint until scrolled
   near. This is what makes the menu-open scroll-lock cheap — Safari
   relayouts the page when the body locks, and these sections opt out
   of that work while off-screen. */
.ix .ix-moat,
.ix .ix-idea:not(.ix-standard),
.ix .ix-end,
.ix .invar-production {
  /* NOT .ix-newsletter-hero: content-visibility implies paint
     containment, which clips its 100vw ::before glow to the 46rem box.
     NOT .ix-start either: the same paint containment clips its hover
     lift (top border shaved at the grid's edge) and the card shadows
     spilling below the box. NOT .ix-idea.ix-standard: its CTA's hover
     shadow ends 2px above the box's bottom edge and gets beheaded. */
@media (min-width: 960px) {
  /* the hairline is painted OUT of flow (::after on the divider's own
     64–65px row) — the title box stays byte-identical to the homepage's,
     so the logo doesn't shift when navigating between layouts */
  .VPNavBarTitle.has-sidebar .title {
    /* transparent, not none — the homepage title carries the same 1px
       transparent border, and the box must match it exactly */
    border-bottom-color: transparent !important;
    position: relative;
  }
  .VPNavBarTitle.has-sidebar .title::after {
    content: '';
    position: absolute;
    left: 0;
    right: 0;
    bottom: -1px;
    height: 1px;
    background: color-mix(in srgb, var(--vp-c-gutter) 30%, transparent);
  }
}

